"""Minimal, valid PE32+ kernel-mode drivers generated by NK for negative
loader tests: one with an intentionally unresolvable kernel symbol, and one
importing from an intentionally nonexistent library module.

These binaries contain no Windows code, work on both x86-64 and arm64, and
stay valid regardless of how much of the Windows ABI NK implements in the
future. Their `DriverEntry` is a trap instruction (`ud2` / `brk #0`) so any
bug that ever executed an image whose imports failed to bind would fault at
once.
"""

import struct

MACHINE = {
    "x86_64": 0x8664,
    "aarch64": 0xAA64,
}

# Trap instructions at DriverEntry (RVA 0x1000): must never execute.
TRAP_CODE = {
    "x86_64": b"\x0f\x0b",          # ud2
    "aarch64": b"\x00\x00\x20\xd4",  # brk #0
}

SUBSYSTEM_NATIVE = 1
SECTION_ALIGNMENT = 0x1000
FILE_ALIGNMENT = 0x200
IMAGE_BASE = 0x140000000

SCN_MEM_DISCARDABLE = 0x02000000
SCN_MEM_EXECUTE = 0x20000000
SCN_MEM_READ = 0x40000000
SCN_MEM_WRITE = 0x80000000

# The two NK-owned negative loader fixtures staged into the boot volume
# when drivers are included.
NEGATIVE_FIXTURES = (
    ("unresolved.sys", b"ntoskrnl.exe", b"NkIntentionalMissingExport"),
    ("nomodule.sys", b"nk-nonexistent-lib.sys", b"NkMissingLibraryExport"),
)


def _pad(data: bytes, size: int) -> bytes:
    if len(data) > size:
        raise ValueError(f"section overflow: {len(data)} > {size}")
    return data + b"\x00" * (size - len(data))


def build_pe(arch: str, dll: bytes, symbol: bytes) -> bytes:
    """Build a valid PE32+ native kernel driver for `arch` with one import
    (`dll!symbol`), a valid `.reloc` table, and a trapping `DriverEntry`."""
    if arch not in MACHINE:
        raise ValueError(f"unsupported arch {arch!r}")

    # Layout (in memory / in file):
    #   0x0000 / 0x0000 : DOS + PE headers + 3 section headers (0x200 bytes)
    #   0x1000 / 0x0200 : .text  (R-X, 0x200 bytes, trapping DriverEntry)
    #   0x2000 / 0x0400 : .rdata (RW-, 0x200 bytes, import directory + INT/IAT)
    #   0x3000 / 0x0600 : .reloc (R-D, 0x200 bytes, valid empty reloc block)
    text_rva, text_off = 0x1000, 0x200
    rdata_rva, rdata_off = 0x2000, 0x400
    reloc_rva, reloc_off = 0x3000, 0x600
    size_of_image = 0x4000

    # --- .rdata: import directory, INT, IAT, DLL name, Hint/Name ---
    # 0x00..0x28: two IMAGE_IMPORT_DESCRIPTORs (1 real + 1 NUL terminator)
    # 0x28..0x38: INT (OriginalFirstThunk): 1 entry + NUL
    # 0x38..0x48: IAT (FirstThunk): 1 entry + NUL
    # 0x48..    : DLL name (NUL-terminated, 2-byte aligned)
    #           : IMAGE_IMPORT_BY_NAME (u16 hint=0, NUL-terminated symbol)
    int_rva = rdata_rva + 0x28
    iat_rva = rdata_rva + 0x38
    dll_rva = rdata_rva + 0x48
    dll_bytes = dll + b"\x00"
    if len(dll_bytes) % 2:
        dll_bytes += b"\x00"
    hint_rva = dll_rva + len(dll_bytes)
    hint_bytes = struct.pack("<H", 0) + symbol + b"\x00"

    import_desc = struct.pack("<IIIII", int_rva, 0, 0, dll_rva, iat_rva)
    null_desc = b"\x00" * 20
    thunks = struct.pack("<QQ", hint_rva, 0)
    rdata = _pad(import_desc + null_desc + thunks + thunks + dll_bytes + hint_bytes, FILE_ALIGNMENT)

    # --- .text ---
    text = _pad(TRAP_CODE[arch], FILE_ALIGNMENT)

    # --- .reloc: one empty 8-byte block for page 0x1000 ---
    reloc_bytes = struct.pack("<II", text_rva, 8)
    reloc = _pad(reloc_bytes, FILE_ALIGNMENT)

    # --- Headers ---
    dos = bytearray(0x80)
    dos[0:2] = b"MZ"
    struct.pack_into("<I", dos, 0x3C, 0x80)

    pe_sig = b"PE\x00\x00"
    # COFF header: Machine, NumberOfSections=3, TimeDateStamp=0, SymTab=0,
    # NumSyms=0, SizeOfOptionalHeader=0xF0, Characteristics=0x0022.
    coff = struct.pack("<HHIIIHH", MACHINE[arch], 3, 0, 0, 0, 0xF0, 0x0022)

    # Optional Header (PE32+, 240 bytes = 112 fixed + 16 * 8 data directories).
    opt = bytearray(0xF0)
    struct.pack_into("<H", opt, 0, 0x020B)               # Magic: PE32+
    struct.pack_into("<I", opt, 16, text_rva)            # AddressOfEntryPoint
    struct.pack_into("<Q", opt, 24, IMAGE_BASE)          # ImageBase
    struct.pack_into("<I", opt, 32, SECTION_ALIGNMENT)   # SectionAlignment
    struct.pack_into("<I", opt, 36, FILE_ALIGNMENT)      # FileAlignment
    struct.pack_into("<H", opt, 40, 10)                  # MajorOSVersion
    struct.pack_into("<H", opt, 48, 10)                  # MajorSubsystemVersion
    struct.pack_into("<I", opt, 56, size_of_image)       # SizeOfImage
    struct.pack_into("<I", opt, 60, FILE_ALIGNMENT)      # SizeOfHeaders
    struct.pack_into("<H", opt, 68, SUBSYSTEM_NATIVE)    # Subsystem
    struct.pack_into("<I", opt, 108, 16)                 # NumberOfRvaAndSizes
    # DIR_IMPORT (index 1)
    struct.pack_into("<II", opt, 112 + 8 * 1, rdata_rva, 40)
    # DIR_BASERELOC (index 5)
    struct.pack_into("<II", opt, 112 + 8 * 5, reloc_rva, len(reloc_bytes))

    def sec_hdr(name: bytes, vsize: int, rva: int, rsize: int, roff: int, chars: int) -> bytes:
        return struct.pack("<8sIIIIIIHHI", name.ljust(8, b"\x00"), vsize, rva, rsize, roff, 0, 0, 0, 0, chars)

    sections = b"".join([
        sec_hdr(b".text", len(TRAP_CODE[arch]), text_rva, FILE_ALIGNMENT, text_off,
                SCN_MEM_READ | SCN_MEM_EXECUTE),
        sec_hdr(b".rdata", FILE_ALIGNMENT, rdata_rva, FILE_ALIGNMENT, rdata_off,
                SCN_MEM_READ | SCN_MEM_WRITE),
        sec_hdr(b".reloc", len(reloc_bytes), reloc_rva, FILE_ALIGNMENT, reloc_off,
                SCN_MEM_READ | SCN_MEM_DISCARDABLE),
    ])

    headers = _pad(bytes(dos) + pe_sig + coff + bytes(opt) + sections, FILE_ALIGNMENT)
    return headers + text + rdata + reloc


def generate_all(arch: str):
    """Yield `(filename, pe_bytes)` for every NK-owned negative loader fixture."""
    for name, dll, symbol in NEGATIVE_FIXTURES:
        yield name, build_pe(arch, dll, symbol)
